563	func (req CreateAuthorizationRequest) validatePresent() error {
564		missing := []string{}
565		if strings.TrimSpace(req.Operator) == "" {
566			missing = append(missing, "operator")
567		}
568		if strings.TrimSpace(req.Reason) == "" {
569			missing = append(missing, "reason")
570		}
571		if strings.TrimSpace(req.RequestID) == "" {
572			missing = append(missing, "request_id")
573		}
574		if strings.TrimSpace(req.AuthID) == "" {
575			missing = append(missing, "auth_id")
576		}
577		if strings.TrimSpace(req.ItemID) == "" {
578			missing = append(missing, "item_id")
579		}
580		if strings.TrimSpace(req.TrusteeID) == "" {
581			missing = append(missing, "trustee_id")
582		}
583		if strings.TrimSpace(req.ToID) == "" {
584			missing = append(missing, "to_id")
585		}
586		if strings.TrimSpace(req.ExpectedOwner) == "" {
587			missing = append(missing, "expected_owner")
588		}
589		if req.ExpectedVer <= 0 {
590			missing = append(missing, "expected_version")
591		}
592		if req.ExpiresAt.IsZero() {
593			missing = append(missing, "expires_at")
594		}
595		if len(missing) > 0 {
596			return fmt.Errorf("%w: 创建授权请求缺少必填字段 %s", ErrInvalidArgument, strings.Join(missing, ", "))
597		}
598		if req.Price < 0 {
599			return fmt.Errorf("%w: 成交价款 %d 不能为负", ErrInvalidArgument, req.Price)
600		}
601		return nil
602	}
