624	// CreateAuthorization 由当前持有人为一件已发行藏品创建限时、一次性的
625	// 代转授权：指定唯一授权编号、受托账户、固定接收账户、绝对到期时间，
626	// 以及期望持有人与期望版本。授权绑定创建时的持有版本，不改变持有关系，
627	// 也不限制持有人继续直接转让。受托人不能是授权人；受托人可与接收人
628	// 相同，但接收人也不能是授权人。到期时间必须晚于当前时间。
629	//
630	// 请求号与发行、转让共用同一操作者的请求号范围：相同业务参数重提返回
631	// 首次结果（成功或状态类业务拒绝），参数变化返回 ErrRequestConflict；
632	// 参数错误与引用不存在不占用请求号。
633	func (r *Registry) CreateAuthorization(req CreateAuthorizationRequest) (CreateAuthorizationResult, error) {
634		if err := req.validatePresent(); err != nil {
635			return CreateAuthorizationResult{}, err
636		}
637		r.mu.Lock()
638		defer r.mu.Unlock()
639		if err := r.checkOpen(); err != nil {
640			return CreateAuthorizationResult{}, err
641		}
642	
643		now := r.now()
644		key := requestKey(req.Operator, req.RequestID)
645		sig := createAuthzParamsSig(req)
646		if prev, ok := r.state.Requests[key]; ok {
647			return r.replayCreateAuthz(prev, sig)
648		}
649	
650		if bizErr := r.checkCreateAuthorization(req, now); bizErr != nil {
651			if !isValidationErr(bizErr) {
652				// 状态类业务拒绝（编号占用、停用、同人、版本不符、到期时间
653				// 已过等）占用请求号并落盘；参数错误与引用不存在不占用。
654				r.state.Requests[key] = request{
655					Operator: req.Operator, RequestID: req.RequestID, Kind: "auth_create",
656					Params: sig, Rejected: true, Reason: errCode(bizErr),
657					AuthID: req.AuthID, ItemID: req.ItemID,
658				}
659				_ = r.commit()
660			}
661			return CreateAuthorizationResult{AuthID: req.AuthID, Err: bizErr}, bizErr
662		}
663	
664		h := r.state.Holdings[req.ItemID]
665		a := authzRec{
666			ID: req.AuthID, ItemID: req.ItemID, GranterID: req.Operator,
667			TrusteeID: req.TrusteeID, ToID: req.ToID, ExpiresAt: req.ExpiresAt,
668			GrantVer: h.Version, Price: req.Price, CreatedAt: now,
669		}
670		r.state.Authzs[req.AuthID] = a
671		authSeq := r.state.NextAuthSeq + 1
672		r.state.NextAuthSeq = authSeq
673		r.state.AuthEvents = append(r.state.AuthEvents, authzEvent{
674			Seq: authSeq, AuthID: req.AuthID, ItemID: req.ItemID, Kind: "create",
675			Operator: req.Operator, Reason: req.Reason, RequestID: req.RequestID,
676			FromStatus: "", ToStatus: AuthActive, OccurredAt: now,
677		})
678		r.state.Requests[key] = request{
679			Operator: req.Operator, RequestID: req.RequestID, Kind: "auth_create",
680			Params: sig, AuthID: req.AuthID, ItemID: req.ItemID, Version: h.Version,
681		}
682		if err := r.commit(); err != nil {
683			return CreateAuthorizationResult{}, err
684		}
685		return CreateAuthorizationResult{AuthID: req.AuthID, Status: AuthActive, GrantVer: h.Version}, nil
686	}
687	
688	func (r *Registry) checkCreateAuthorization(req CreateAuthorizationRequest, now time.Time) error {
689		h, ok := r.state.Holdings[req.ItemID]
690		if !ok {
691			if _, itemExists := r.state.Items[req.ItemID]; !itemExists {
692				return fmt.Errorf("%w: 藏品 %s", ErrNotFound, req.ItemID)
693			}
694			return fmt.Errorf("%w: 藏品 %s 没有持有记录", ErrNotFound, req.ItemID)
695		}
696		op, ok := r.state.Accounts[req.Operator]
697		if !ok {
698			return fmt.Errorf("%w: 授权人账户 %s", ErrNotFound, req.Operator)
699		}
700		trustee, ok := r.state.Accounts[req.TrusteeID]
701		if !ok {
702			return fmt.Errorf("%w: 受托人账户 %s", ErrNotFound, req.TrusteeID)
703		}
704		to, ok := r.state.Accounts[req.ToID]
705		if !ok {
706			return fmt.Errorf("%w: 接收账户 %s", ErrNotFound, req.ToID)
707		}
708		if req.TrusteeID == req.Operator {
709			return fmt.Errorf("%w: 受托人不能是授权人 %s", ErrSameAccount, req.Operator)
710		}
711		if req.ToID == req.Operator {
712			return fmt.Errorf("%w: 接收人不能是授权人 %s", ErrSameAccount, req.Operator)
713		}
714		if !op.Active {
715			return fmt.Errorf("%w: 授权人账户 %s", ErrAccountInactive, req.Operator)
716		}
717		if !trustee.Active {
718			return fmt.Errorf("%w: 受托人账户 %s", ErrAccountInactive, req.TrusteeID)
719		}
720		if !to.Active {
721			return fmt.Errorf("%w: 接收账户 %s", ErrAccountInactive, req.ToID)
722		}
723		// 授权编号占用是对象级冲突，优先于当前时间与持有版本检查。
724		if _, exists := r.state.Authzs[req.AuthID]; exists {
725			return fmt.Errorf("%w: 授权编号 %s 已被占用", ErrAlreadyExists, req.AuthID)
726		}
727		// 到期时间不晚于当前时间即为参数错误；从到期时间点起不可使用。
728		if !req.ExpiresAt.After(now) {
729			return fmt.Errorf("%w: 到期时间 %s 必须晚于当前时间",
730				ErrInvalidArgument, req.ExpiresAt.Format(time.RFC3339Nano))
731		}
732		if h.OwnerID != req.ExpectedOwner || h.Version != req.ExpectedVer ||
733			req.Operator != h.OwnerID {
734			return fmt.Errorf("%w: 藏品 %s 当前为 %s 版本 %d",
735				ErrConflict, req.ItemID, h.OwnerID, h.Version)
736		}
737		return nil
738	}
739	
740	func (r *Registry) replayCreateAuthz(prev request, sig string) (CreateAuthorizationResult, error) {
741		if prev.Kind != "auth_create" || prev.Params != sig {
742			return CreateAuthorizationResult{}, fmt.Errorf("%w: 操作者 %s 的请求号 %s 已用于不同请求",
743				ErrRequestConflict, prev.Operator, prev.RequestID)
744		}
745		res := CreateAuthorizationResult{AuthID: prev.AuthID, GrantVer: prev.Version,
746			Status: AuthActive, Replayed: true}
747		if prev.Rejected {
748			res.Err = codeErr(prev.Reason)
749			return res, res.Err
750		}
751		return res, nil
752	}
753	
754	func revokeAuthzParamsSig(req RevokeAuthorizationRequest) string {
755		b, _ := json.Marshal(struct {
756			Kind   string `json:"kind"`
757			AuthID string `json:"auth_id"`
758			Reason string `json:"reason"`
759		}{"auth_revoke", req.AuthID, req.Reason})
760		return string(b)
761	}
762	
763	// RevokeAuthorization 撤销一份尚未使用的代转授权。仅授权人可以撤销；
764	// 已使用的授权不能撤销（返回 ErrAuthorizationUsed）。授权已撤销时再次
765	// 撤销不新增授权变更记录，按成功返回。请求号语义与其他操作一致。
766	func (r *Registry) RevokeAuthorization(req RevokeAuthorizationRequest) (RevokeAuthorizationResult, error) {
767		missing := []string{}
768		if strings.TrimSpace(req.Operator) == "" {
769			missing = append(missing, "operator")
770		}
771		if strings.TrimSpace(req.Reason) == "" {
772			missing = append(missing, "reason")
773		}
774		if strings.TrimSpace(req.RequestID) == "" {
775			missing = append(missing, "request_id")
776		}
777		if strings.TrimSpace(req.AuthID) == "" {
778			missing = append(missing, "auth_id")
779		}
780		if len(missing) > 0 {
781			return RevokeAuthorizationResult{}, fmt.Errorf("%w: 撤销授权请求缺少必填字段 %s",
782				ErrInvalidArgument, strings.Join(missing, ", "))
783		}
784		r.mu.Lock()
785		defer r.mu.Unlock()
786		if err := r.checkOpen(); err != nil {
787			return RevokeAuthorizationResult{}, err
788		}
789	
790		now := r.now()
791		key := requestKey(req.Operator, req.RequestID)
792		sig := revokeAuthzParamsSig(req)
793		if prev, ok := r.state.Requests[key]; ok {
794			return r.replayRevokeAuthz(prev, sig)
795		}
796	
797		a, ok := r.state.Authzs[req.AuthID]
798		if !ok {
799			// 引用不存在不占用请求号。
800			err := fmt.Errorf("%w: 授权 %s", ErrNotFound, req.AuthID)
801			return RevokeAuthorizationResult{AuthID: req.AuthID, Err: err}, err
802		}
803		if a.GranterID != req.Operator {
804			bizErr := fmt.Errorf("%w: 只有授权人 %s 可以撤销授权 %s",
805				ErrForbidden, a.GranterID, req.AuthID)
806			r.recordAuthzRequest(key, sig, req, "auth_revoke", bizErr)
807			return RevokeAuthorizationResult{AuthID: req.AuthID, Err: bizErr}, bizErr
808		}
809		switch authzCurrentStatus(a, now) {
810		case AuthUsed:
811			bizErr := fmt.Errorf("%w: 授权 %s 已使用，不能撤销", ErrAuthorizationUsed, req.AuthID)
812			r.recordAuthzRequest(key, sig, req, "auth_revoke", bizErr)
813			return RevokeAuthorizationResult{AuthID: req.AuthID, Err: bizErr}, bizErr
814		case AuthRevoked:
815			// 已撤销是幂等终态：不新增授权变更记录；该请求号仍登记为成功，
816			// 相同请求重放回放同一结果。
817			r.state.Requests[key] = request{
818				Operator: req.Operator, RequestID: req.RequestID, Kind: "auth_revoke",
819				Params: sig, AuthID: req.AuthID,
820			}
821			if err := r.commit(); err != nil {
822				return RevokeAuthorizationResult{}, err
823			}
824			return RevokeAuthorizationResult{AuthID: req.AuthID, Status: AuthRevoked}, nil
825		}
826	
827		from := AuthActive
828		if authzCurrentStatus(a, now) == AuthExpired {
829			from = AuthExpired
830		}
831		a.Status = "revoked"
832		a.RevokedAt = now
833		r.state.Authzs[req.AuthID] = a
834		authSeq := r.state.NextAuthSeq + 1
835		r.state.NextAuthSeq = authSeq
836		r.state.AuthEvents = append(r.state.AuthEvents, authzEvent{
837			Seq: authSeq, AuthID: req.AuthID, ItemID: a.ItemID, Kind: "revoke",
838			Operator: req.Operator, Reason: req.Reason, RequestID: req.RequestID,
839			FromStatus: from, ToStatus: AuthRevoked, OccurredAt: now,
840		})
841		r.state.Requests[key] = request{
842			Operator: req.Operator, RequestID: req.RequestID, Kind: "auth_revoke",
843			Params: sig, AuthID: req.AuthID,
844		}
845		if err := r.commit(); err != nil {
846			return RevokeAuthorizationResult{}, err
847		}
848		return RevokeAuthorizationResult{AuthID: req.AuthID, Status: AuthRevoked}, nil
849	}
850	
851	// recordAuthzRequest 记录授权类操作的状态类业务拒绝并尽力落盘。
852	func (r *Registry) recordAuthzRequest(key, sig string, req RevokeAuthorizationRequest, kind string, bizErr error) {
853		r.state.Requests[key] = request{
854			Operator: req.Operator, RequestID: req.RequestID, Kind: kind,
855			Params: sig, Rejected: true, Reason: errCode(bizErr), AuthID: req.AuthID,
856		}
857		_ = r.commit()
858	}
859	
860	func (r *Registry) replayRevokeAuthz(prev request, sig string) (RevokeAuthorizationResult, error) {
861		if prev.Kind != "auth_revoke" || prev.Params != sig {
862			return RevokeAuthorizationResult{}, fmt.Errorf("%w: 操作者 %s 的请求号 %s 已用于不同请求",
863				ErrRequestConflict, prev.Operator, prev.RequestID)
864		}
865		res := RevokeAuthorizationResult{AuthID: prev.AuthID, Status: AuthRevoked, Replayed: true}
866		if prev.Rejected {
867			res.Err = codeErr(prev.Reason)
868			res.Status = ""
869			return res, res.Err
870		}
871		return res, nil
872	}
