878			Reason string `json:"reason"`
879		}{"proxy_transfer", req.AuthID, req.Reason})
880		return string(b)
881	}
882	
883	// ProxyTransfer 由受托人凭授权发起一次性代转。藏品与接收人均以授权
884	// 记载为准，请求本身不能指定。成功后持有人变为授权中的接收人、持有
885	// 版本加一，授权记为已使用并关联该笔转让；代转同样出现在藏品历史中，
886	// 操作者记为实际受托账户并可通过授权编号追溯。
887	//
888	// 非受托人（ErrForbidden）、授权已撤销（ErrAuthorizationRevoked）、
889	// 已到期（ErrAuthorizationExpired）、已使用（ErrAuthorizationUsed）、
890	// 任一相关账户停用（ErrAccountInactive）以及持有版本已变化
891	// （ErrConflict，即使藏品回到授权人手中也不恢复）分别明确拒绝，拒绝
892	// 不改变持有或授权状态。成功代转用原请求号重放时，即使授权已到期、
893	// 账户已停用或藏品再次易手，仍返回首次的转让结果。
894	func (r *Registry) ProxyTransfer(req ProxyTransferRequest) (ProxyTransferResult, error) {
895		missing := []string{}
896		if strings.TrimSpace(req.Operator) == "" {
897			missing = append(missing, "operator")
898		}
899		if strings.TrimSpace(req.Reason) == "" {
900			missing = append(missing, "reason")
901		}
902		if strings.TrimSpace(req.RequestID) == "" {
903			missing = append(missing, "request_id")
904		}
905		if strings.TrimSpace(req.AuthID) == "" {
906			missing = append(missing, "auth_id")
907		}
908		if len(missing) > 0 {
909			return ProxyTransferResult{}, fmt.Errorf("%w: 代转请求缺少必填字段 %s",
910				ErrInvalidArgument, strings.Join(missing, ", "))
911		}
912		r.mu.Lock()
913		defer r.mu.Unlock()
914		if err := r.checkOpen(); err != nil {
915			return ProxyTransferResult{}, err
916		}
917	
918		now := r.now()
919		key := requestKey(req.Operator, req.RequestID)
920		sig := proxyTransferParamsSig(req)
921		if prev, ok := r.state.Requests[key]; ok {
922			return r.replayProxyTransfer(prev, sig)
923		}
924	
925		if bizErr := r.checkProxyTransfer(req, now); bizErr != nil {
926			if !isValidationErr(bizErr) {
927				r.state.Requests[key] = request{
928					Operator: req.Operator, RequestID: req.RequestID, Kind: "proxy_transfer",
929					Params: sig, Rejected: true, Reason: errCode(bizErr), AuthID: req.AuthID,
930				}
931				_ = r.commit()
932			}
933			return ProxyTransferResult{AuthID: req.AuthID, Err: bizErr}, bizErr
934		}
935	
936		a := r.state.Authzs[req.AuthID]
937		// 代转价款以授权创建时记载为准，执行时不得改价；余款归转让前持有
938		// 人（授权人），不记给受托人。持有变化、历史、应付明细与授权使用
939		// 状态在同一临界区内一次落盘；历史记录实际受托账户并可按授权编号
940		// 追溯。
941		out := r.applyTransfer(a.ItemID, a.ToID, req.Operator, req.Reason, req.RequestID, a.ID, a.Price)
942		a.Status = "used"
943		a.UsedTxSeq = out.seq
944		a.UsedAt = now
945		r.state.Authzs[a.ID] = a
946		authSeq := r.state.NextAuthSeq + 1
947		r.state.NextAuthSeq = authSeq
948		r.state.AuthEvents = append(r.state.AuthEvents, authzEvent{
949			Seq: authSeq, AuthID: a.ID, ItemID: a.ItemID, Kind: "use",
950			Operator: req.Operator, Reason: req.Reason, RequestID: req.RequestID,
951			FromStatus: AuthActive, ToStatus: AuthUsed, TxSeq: out.seq, OccurredAt: now,
952		})
953		r.state.Requests[key] = request{
954			Operator: req.Operator, RequestID: req.RequestID, Kind: "proxy_transfer",
955			Params: sig, AuthID: a.ID, ItemID: a.ItemID, FromID: out.fromID, ToID: a.ToID,
956			Version: out.toVer(), TxSeq: out.seq,
957		}
958		if err := r.commit(); err != nil {
959			return ProxyTransferResult{}, err
960		}
961		return ProxyTransferResult{AuthID: a.ID, ItemID: a.ItemID, FromID: out.fromID,
962			ToID: a.ToID, Version: out.toVer(), TxSeq: out.seq,
963			Price: out.royalty.Price, Payables: publicPayables(out.royalty.Payees),
964			Remainder: out.royalty.Remainder}, nil
965	}
966	
967	func (r *Registry) checkProxyTransfer(req ProxyTransferRequest, now time.Time) error {
968		a, ok := r.state.Authzs[req.AuthID]
969		if !ok {
970			return fmt.Errorf("%w: 授权 %s", ErrNotFound, req.AuthID)
971		}
972		op, ok := r.state.Accounts[req.Operator]
973		if !ok {
974			return fmt.Errorf("%w: 受托人账户 %s", ErrNotFound, req.Operator)
975		}
976		granter, gOk := r.state.Accounts[a.GranterID]
977		to, tOk := r.state.Accounts[a.ToID]
978		if req.Operator != a.TrusteeID {
979			return fmt.Errorf("%w: 账户 %s 不是授权 %s 的受托人",
980				ErrForbidden, req.Operator, req.AuthID)
981		}
982		if !gOk {
983			return fmt.Errorf("%w: 授权人账户 %s", ErrNotFound, a.GranterID)
984		}
985		if !tOk {
986			return fmt.Errorf("%w: 接收账户 %s", ErrNotFound, a.ToID)
987		}
988		if !op.Active {
989			return fmt.Errorf("%w: 受托人账户 %s", ErrAccountInactive, req.Operator)
990		}
991		if !granter.Active {
992			return fmt.Errorf("%w: 授权人账户 %s", ErrAccountInactive, a.GranterID)
993		}
994		if !to.Active {
995			return fmt.Errorf("%w: 接收账户 %s", ErrAccountInactive, a.ToID)
996		}
997		switch authzCurrentStatus(a, now) {
998		case AuthRevoked:
999			return fmt.Errorf("%w: 授权 %s", ErrAuthorizationRevoked, req.AuthID)
1000		case AuthExpired:
1001			return fmt.Errorf("%w: 授权 %s", ErrAuthorizationExpired, req.AuthID)
1002		case AuthUsed:
1003			return fmt.Errorf("%w: 授权 %s", ErrAuthorizationUsed, req.AuthID)
1004		}
1005		// 授权只在创建时绑定的持有版本上有效；版本单调递增，藏品即使回到
1006		// 授权人手中也不会回到旧版本，旧授权据此永久失效。
1007		h, ok := r.state.Holdings[a.ItemID]
1008		if !ok {
1009			return fmt.Errorf("%w: 藏品 %s 没有持有记录", ErrNotFound, a.ItemID)
1010		}
1011		if h.OwnerID != a.GranterID || h.Version != a.GrantVer {
1012			return fmt.Errorf("%w: 藏品 %s 当前为 %s 版本 %d，授权绑定 %s 版本 %d",
1013				ErrConflict, a.ItemID, h.OwnerID, h.Version, a.GranterID, a.GrantVer)
1014		}
1015		return nil
1016	}
1017	
1018	func (r *Registry) replayProxyTransfer(prev request, sig string) (ProxyTransferResult, error) {
1019		if prev.Kind != "proxy_transfer" || prev.Params != sig {
1020			return ProxyTransferResult{}, fmt.Errorf("%w: 操作者 %s 的请求号 %s 已用于不同请求",
1021				ErrRequestConflict, prev.Operator, prev.RequestID)
1022		}
1023		res := ProxyTransferResult{AuthID: prev.AuthID, ItemID: prev.ItemID, FromID: prev.FromID,
1024			ToID: prev.ToID, Version: prev.Version, TxSeq: prev.TxSeq, Replayed: true}
1025		if prev.Rejected {
1026			res.Err = codeErr(prev.Reason)
1027			return res, res.Err
1028		}
1029		// 回放首次成功的金额：授权到期、账户停用或藏品再次易手后仍返回
1030		// 原价款与应付明细，不重复计入。
1031		res.Price, res.Payables, res.Remainder = r.royaltyOfTx(prev.TxSeq)
1032		return res, nil
1033	}
1034	
1035	// ---- 授权查询 ----
1036	
1037	// GetAuthorization 按编号查询授权内容与撤销、使用状态。授权不存在时
1038	// 返回包裹 ErrNotFound 的错误；返回的 Status 按当前时间实时计算，
1039	// 到期但尚未终结的授权返回 AuthExpired。
1040	func (r *Registry) GetAuthorization(authID string) (Authorization, error) {
1041		r.mu.Lock()
1042		defer r.mu.Unlock()
1043		if err := r.checkOpen(); err != nil {
1044			return Authorization{}, err
1045		}
1046		a, ok := r.state.Authzs[authID]
1047		if !ok {
1048			return Authorization{}, fmt.Errorf("%w: 授权 %s", ErrNotFound, authID)
1049		}
1050		return Authorization{
1051			ID: a.ID, ItemID: a.ItemID, GranterID: a.GranterID, TrusteeID: a.TrusteeID,
1052			ToID: a.ToID, ExpiresAt: a.ExpiresAt, GrantVer: a.GrantVer, Price: a.Price,
1053			Status:    authzCurrentStatus(a, r.now()),
1054			UsedTxSeq: a.UsedTxSeq, UsedAt: a.UsedAt, CreatedAt: a.CreatedAt,
1055			RevokedAt: a.RevokedAt,
1056		}, nil
1057	}
1058	
1059	// AuthorizationHistory 按藏品查看授权变更记录（创建、撤销、使用），
1060	// 按发生先后排列；每条记录包含操作者、原因、请求号与前后状态。藏品
1061	// 不存在时返回包裹 ErrNotFound 的错误。
1062	func (r *Registry) AuthorizationHistory(itemID string) ([]AuthorizationEvent, error) {
1063		r.mu.Lock()
1064		defer r.mu.Unlock()
1065		if err := r.checkOpen(); err != nil {
1066			return nil, err
1067		}
1068		if _, ok := r.state.Items[itemID]; !ok {
1069			return nil, fmt.Errorf("%w: 藏品 %s", ErrNotFound, itemID)
1070		}
1071		out := make([]AuthorizationEvent, 0)
1072		for _, e := range r.state.AuthEvents {
1073			if e.ItemID != itemID {
1074				continue
1075			}
1076			out = append(out, AuthorizationEvent{
1077				Seq: e.Seq, AuthID: e.AuthID, ItemID: e.ItemID, Kind: e.Kind,
1078				Operator: e.Operator, Reason: e.Reason, RequestID: e.RequestID,
1079				FromStatus: e.FromStatus, ToStatus: e.ToStatus, TxSeq: e.TxSeq,
1080				OccurredAt: e.OccurredAt,
1081			})
1082		}
1083		return out, nil
1084	}
1085	
1086	// ---- 查询 ----
1087	
1088	// GetItem 查询单件藏品的静态登记信息；不存在时返回包裹 ErrNotFound 的错误。
1089	func (r *Registry) GetItem(id string) (Item, error) {
1090		r.mu.Lock()
1091		defer r.mu.Unlock()
1092		if err := r.checkOpen(); err != nil {
1093			return Item{}, err
1094		}
1095		it, ok := r.state.Items[id]
1096		if !ok {
1097			return Item{}, fmt.Errorf("%w: 藏品 %s", ErrNotFound, id)
1098		}
1099		return Item{ID: it.ID, SeriesID: it.SeriesID, BatchNo: it.BatchNo,
1100			Metadata: it.Metadata, IssuedTxID: it.IssuedTxID}, nil
1101	}
1102	
1103	// GetHolding 查询藏品当前持有状态；藏品不存在时返回包裹 ErrNotFound 的错误。
1104	func (r *Registry) GetHolding(itemID string) (Holding, error) {
1105		r.mu.Lock()
1106		defer r.mu.Unlock()
1107		if err := r.checkOpen(); err != nil {
1108			return Holding{}, err
1109		}
1110		h, ok := r.state.Holdings[itemID]
1111		if !ok {
1112			return Holding{}, fmt.Errorf("%w: 藏品 %s", ErrNotFound, itemID)
1113		}
1114		return Holding{ItemID: h.ItemID, OwnerID: h.OwnerID, Version: h.Version}, nil
1115	}
1116	
1117	// HoldingsOf 查询某账户当前持有的全部藏品。账户不存在时返回包裹
1118	// ErrNotFound 的错误；停用账户仍可正常查询。
1119	func (r *Registry) HoldingsOf(accountID string) ([]Holding, error) {
1120		r.mu.Lock()
1121		defer r.mu.Unlock()
1122		if err := r.checkOpen(); err != nil {
1123			return nil, err
1124		}
1125		if _, ok := r.state.Accounts[accountID]; !ok {
1126			return nil, fmt.Errorf("%w: 账户 %s", ErrNotFound, accountID)
1127		}
1128		out := make([]Holding, 0)
1129		for _, h := range r.state.Holdings {
1130			if h.OwnerID == accountID {
1131				out = append(out, Holding{ItemID: h.ItemID, OwnerID: h.OwnerID, Version: h.Version})
1132			}
1133		}
1134		sort.Slice(out, func(i, j int) bool { return out[i].ItemID < out[j].ItemID })
1135		return out, nil
1136	}
1137	
1138	// History 查询藏品的发行与历次成功转让，按发生先后排列。发行记录的
1139	// 前持有人为空、前版本为 0。重复提交不会产生额外历史。藏品不存在时
1140	// 返回包裹 ErrNotFound 的错误。
1141	func (r *Registry) History(itemID string) ([]HistoryEntry, error) {
1142		r.mu.Lock()
1143		defer r.mu.Unlock()
1144		if err := r.checkOpen(); err != nil {
1145			return nil, err
1146		}
1147		if _, ok := r.state.Items[itemID]; !ok {
1148			return nil, fmt.Errorf("%w: 藏品 %s", ErrNotFound, itemID)
1149		}
1150		out := make([]HistoryEntry, 0)
1151		for _, e := range r.state.History {
1152			if e.ItemID != itemID {
1153				continue
1154			}
1155			out = append(out, HistoryEntry{
1156				Seq: e.Seq, Kind: e.Kind, ItemID: e.ItemID, Operator: e.Operator,
1157				Reason: e.Reason, RequestID: e.RequestID, FromID: e.FromID, ToID: e.ToID,
1158				FromVersion: e.FromVersion, ToVersion: e.ToVersion, AuthID: e.AuthID,
1159			})
1160		}
1161		return out, nil
1162	}
1163	
1164	// ---- 幂等辅助 ----
1165	
1166	// requestKey 由完整的操作者账户编号与完整的请求号共同确定一条请求记录。
1167	// 采用 JSON 数组编码而非直接拼接：账户编号或请求号本身允许包含零字符
1168	// （U+0000）等任意字符，直接拼接会让 ("a", "b\x00c") 与 ("a\x00b", "c")
1169	// 之类不同的组合得到相同的键，导致不同账户互相占用请求号、回放别人的
1170	// 结果。JSON 编码对任意字符都无歧义，两个组成部分各自完整参与键的构成。
1171	func requestKey(operator, requestID string) string {
1172		b, _ := json.Marshal([2]string{operator, requestID})
1173		return string(b)
1174	}
1175	
1176	// isValidationErr 判定是否为请求本身不成立的错误：必填缺失，或引用了
1177	// 不存在的账户、系列、藏品。这类请求不占用请求号、不落任何记录，引用
1178	// 对象后来补建后仍可用原请求号完整执行一次；其余拒绝（封存、停用、
1179	// 版本冲突、无权、编号已用、收发同人等状态类业务拒绝）按首次结果记忆
1180	// 并回放。
1181	func isValidationErr(err error) bool {
1182		return errors.Is(err, ErrInvalidArgument) || errors.Is(err, ErrNotFound)
1183	}
1184	
1185	var errCodes = map[error]string{
1186		ErrNotFound:             "not_found",
1187		ErrAlreadyExists:        "already_exists",
1188		ErrAccountInactive:      "account_inactive",
1189		ErrSeriesSealed:         "series_sealed",
1190		ErrConflict:             "conflict",
1191		ErrSameAccount:          "same_account",
1192		ErrForbidden:            "forbidden",
1193		ErrAuthorizationRevoked: "authorization_revoked",
1194		ErrAuthorizationExpired: "authorization_expired",
1195		ErrAuthorizationUsed:    "authorization_used",
1196		ErrRoyaltyFrozen:        "royalty_frozen",
1197		ErrSplitIntentRejected:  "split_intent_rejected",
1198		ErrSplitIntentWithdrawn: "split_intent_withdrawn",
1199		ErrSplitIntentInvalid:   "split_intent_invalid",
1200		ErrSplitIntentExpired:   "split_intent_expired",
1201		ErrSplitAnswered:        "split_answered",
1202	}
1203	
1204	var codeErrs = map[string]error{
1205		"not_found":              ErrNotFound,
1206		"already_exists":         ErrAlreadyExists,
1207		"account_inactive":       ErrAccountInactive,
1208		"series_sealed":          ErrSeriesSealed,
1209		"conflict":               ErrConflict,
1210		"same_account":           ErrSameAccount,
1211		"forbidden":              ErrForbidden,
1212		"authorization_revoked":  ErrAuthorizationRevoked,
1213		"authorization_expired":  ErrAuthorizationExpired,
1214		"authorization_used":     ErrAuthorizationUsed,
1215		"royalty_frozen":         ErrRoyaltyFrozen,
1216		"split_intent_rejected":  ErrSplitIntentRejected,
1217		"split_intent_withdrawn": ErrSplitIntentWithdrawn,
1218		"split_intent_invalid":   ErrSplitIntentInvalid,
1219		"split_intent_expired":   ErrSplitIntentExpired,
1220		"split_answered":         ErrSplitAnswered,
1221	}
1222	
1223	func errCode(err error) string {
1224		for sentinel, code := range errCodes {
1225			if errors.Is(err, sentinel) {
1226				return code
1227			}
1228		}
1229		return "rejected"
1230	}
1231	
1232	func codeErr(code string) error {
1233		if e, ok := codeErrs[code]; ok {
1234			return e
1235		}
1236		return errors.New("registry: 请求曾被拒绝")
1237	}
1238

