	// 保存条件恢复、拒绝条件（期望版本 2 与实际版本 1 不符）仍在：重提
	// 重新保存此次拒绝，返回对应业务错误与藏品编号，不标回放。
	restoreBatchSave(t, r)
	res, err = r.Transfer(req)
	if !errors.Is(err, ErrConflict) {
		t.Fatalf("重提应在保存成功后返回业务拒绝 ErrConflict: %v", err)
	}
