	res, err = r.Transfer(req)
	if !errors.Is(err, ErrConflict) || !res.Replayed ||
		res.ItemID != "i1" || !errors.Is(res.Err, ErrConflict) {
		t.Fatalf("保存后的重提应回放原拒绝: %+v, err %v", res, err)
	}
}

